const frenchOverrides: Partial<Record<keyof typeof english, string>> = {
  "landing.installApp": "Installer l’application",
  "landing.installHintIos": "Sur iPhone et iPad, touchez Partager, puis Ajouter à l’écran d’accueil.",
  "landing.installHintFirefoxAndroid": "Dans Firefox pour Android, ouvrez le menu du navigateur, puis choisissez Installer.",
};

export type TranslationKey = keyof typeof english;

export function hasTranslationKey(key: string): key is TranslationKey {
  return Object.prototype.hasOwnProperty.call(english, key);
}

export function t(key: TranslationKey, values?: Record<string, string | number>): string {
  return tInLocale(key, "en", values);
}

export function tInLocale(
  key: TranslationKey,
  locale: "en" | "fr",
  values?: Record<string, string | number>,
): string {
  const message = locale === "fr" ? frenchOverrides[key] ?? english[key] : english[key];
  if (!values) return message;
  return message.replace(/\{([a-zA-Z0-9_]+)\}/g, (placeholder: string, token: string) =>
    Object.prototype.hasOwnProperty.call(values, token) ? String(values[token]) : placeholder,
  );
}
